import sys
MOD = 998244353

def solve():
    data = list(map(int, sys.stdin.buffer.read().split()))
    n = data[0]
    ys = [n + 1] + [0] * (n + 1)
    for i in range(n):
        x, y = data[1 + 2*i:3 + 2*i]
        ys[x] = y
    dp = [0] * (n + 2)
    dp[0] = 1
    for b in range(1, n + 2):
        low = ys[b]
        total = 0
        for a in range(b):
            high = ys[a]
            if high <= low or dp[a] == 0:
                continue
            vals = [ys[j] for j in range(a + 1, b) if low < ys[j] < high]
            k = len(vals)
            suffix = [0] * (k + 1)
            for j in range(k - 1, -1, -1):
                v = vals[j]
                suffix[j] = max(v, suffix[j + 1])
            minimum = n + 1
            for j, v in enumerate(vals):
                if v < minimum:
                    if v > suffix[j + 1]:
                        break
                    minimum = v
            else:
                total += dp[a]
        dp[b] = total % MOD
    print(dp[-1])

if __name__ == '__main__':
    solve()

