import sys
from collections import deque

MOD = 998244353


def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    n, m = data[:2]
    a = [v - 1 for v in data[2:]]
    indegree = [0] * n
    for v in a:
        indegree[v] += 1

    queue = deque(i for i in range(n) if indegree[i] == 0)
    # dp[u][k-1] counts assignments in the attached trees with x[u] = k.
    # None represents a row consisting entirely of ones.
    dp = [None] * n
    while queue:
        u = queue.popleft()
        v = a[u]
        row = dp[u]
        dest = dp[v]
        if row is None:
            if dest is None:
                dp[v] = list(range(1, m + 1))
            else:
                for j in range(m):
                    dest[j] = dest[j] * (j + 1) % MOD
        else:
            total = 0
            if dest is None:
                for j in range(m):
                    total = (total + row[j]) % MOD
                    row[j] = total
                dp[v] = row
            else:
                for j in range(m):
                    total = (total + row[j]) % MOD
                    dest[j] = dest[j] * total % MOD
            dp[u] = None
        indegree[v] -= 1
        if indegree[v] == 0:
            queue.append(v)

    answer = 1
    for u in range(n):
        if indegree[u] == 0:
            continue
        # All vertices of a directed cycle must have the same value.
        acc = None
        v = u
        while indegree[v]:
            indegree[v] = 0
            row = dp[v]
            if row is not None:
                if acc is None:
                    acc = row
                else:
                    for j in range(m):
                        acc[j] = acc[j] * row[j] % MOD
            dp[v] = None
            v = a[v]
        ways = m if acc is None else sum(acc) % MOD
        answer = answer * ways % MOD
    print(answer)


if __name__ == '__main__':
    main()

