import sys

MOD = 998244353

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    n = data[0]
    a = data[1:]

    spf = list(range(1001))
    for p in range(2, 32):
        if spf[p] == p:
            for v in range(p * p, 1001, p):
                if spf[v] == v:
                    spf[v] = p

    seqs = {}
    for i, x in enumerate(a):
        while x > 1:
            p = spf[x]
            e = 0
            while x % p == 0:
                x //= p
                e += 1
            if p not in seqs:
                seqs[p] = [0] * (n - 1)
            seqs[p][i] = e

    ans = 1
    for p, es in seqs.items():
        limit = max(sum(es), max(es) * (n - 1))
        pw = [1] * (limit + 1)
        for j in range(limit):
            pw[j + 1] = pw[j] * p % MOD

        # Heights are normalized so that the minimum so far is zero.
        dp = [1]
        for i, e in enumerate(es, 1):
            if e == 0:
                dp = [v * pw[h] % MOD for h, v in enumerate(dp)]
                continue
            nd = [0] * (len(dp) + e)
            for h, v in enumerate(dp):
                if not v:
                    continue
                u = h + e
                nd[u] = (nd[u] + v * pw[u]) % MOD
                if h >= e:
                    d = h - e
                    nd[d] = (nd[d] + v * pw[d]) % MOD
                else:
                    # A new minimum raises all i previous heights.
                    nd[0] = (nd[0] + v * pw[(e - h) * i]) % MOD
            dp = nd
        ans = ans * (sum(dp) % MOD) % MOD
    print(ans)

if __name__ == '__main__':
    main()

