import sys
from math import gcd

def solve():
    data = list(map(int, sys.stdin.buffer.read().split()))
    n = data[0]
    a = data[1:]
    del data
    limit = max(a)
    freq = [0] * (limit + 1)
    for x in a:
        freq[x] += 1
    phi = list(range(limit + 1))
    for p in range(2, limit + 1):
        if phi[p] == p:
            for j in range(p, limit + 1, p):
                phi[j] -= phi[j] // p
    rows = [None] * (limit + 1)
    vals = []
    for x in range(1, limit + 1):
        if freq[x]:
            rows[x] = []
            vals.append(x)
    groups = {}
    for d in range(1, limit + 1):
        t = tuple(x for x in range(d, limit + 1, d) if freq[x])
        if not t:
            continue
        g = groups.get(t)
        if g is None:
            g = [0, phi[d]]
            groups[t] = g
            for x in t:
                rows[x].append(g)
        else:
            g[1] += phi[d]
    del groups, phi
    heavy = sorted(
        (x for x in vals if freq[x] * len(rows[x]) > 3 * n),
        key=lambda x: freq[x] * len(rows[x]), reverse=True
    )[:16]
    ans = 0
    power = 1
    out = []
    mod = 998244353
    if not heavy:
        for x in a:
            q = 0
            for g in rows[x]:
                s, c = g
                q += s
                g[0] = s + c * power
            ans = (2 * ans + q) % mod
            out.append(str(ans))
            power = power * 2 % mod
    else:
        h = len(heavy)
        hi = {x: i for i, x in enumerate(heavy)}
        gs = [None] * (limit + 1)
        for x in vals:
            gs[x] = [gcd(x, y) for y in heavy]
        sums = [0] * h
        weights = [0] * h
        indices = range(h)
        for x in a:
            idx = hi.get(x, -1)
            ds = gs[x]
            if idx >= 0:
                q = sums[idx]
                for j in indices:
                    sums[j] += ds[j] * power
                weights[idx] += power
            else:
