def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    values = data[1:]
    limit = max(values)

    # The Grundy number is the number of prime factors with multiplicity.
    omega = bytearray(limit + 1)
    for prime in range(2, limit + 1):
        if omega[prime] == 0:
            power = prime
            while power <= limit:
                for multiple in range(power, limit + 1, power):
                    omega[multiple] += 1
                power *= prime

    result = 0
    for value in values:
        result ^= omega[value]
    print('Anna' if result else 'Bruno')


