import sys
from math import gcd


def main():
    it = iter(map(int, sys.stdin.buffer.read().split()))
    n = next(it)
    budget = next(it)
    rows = []
    upper = 10**18

    for _ in range(n):
        a, p, b, q = next(it), next(it), next(it), next(it)
        # S is at least as cost-efficient as T.
        if a * q < b * p:
            a, p, b, q = b, q, a, p
        upper = min(upper, budget * a // p)
        # a/gcd(a,b) copies of T can be replaced by b/gcd(a,b)
        # copies of S without increasing the cost.
        options = [(t * b, t * q) for t in range(1, a // gcd(a, b))]
        rows.append((a, p, options))

    def feasible(w):
        total = 0
        for a, p, options in rows:
            best = (w + a - 1) // a * p
            for capacity, cost in options:
                remaining = w - capacity
                if remaining > 0:
                    cost += (remaining + a - 1) // a * p
                if cost < best:
                    best = cost
                if remaining <= 0:
                    break
            total += best
            if total > budget:
                return False
        return True

    low, high = 0, upper + 1
    while high - low > 1:
        mid = (low + high) // 2
        if feasible(mid):
            low = mid
        else:
            high = mid
    print(low)


