class Solution:
    def countKReducibleNumbers(self, s: str, k: int) -> int:
        mod = 10**9 + 7
        length = len(s)
        depth = [0] * (length + 1)
        for i in range(2, length + 1):
            depth[i] = depth[i.bit_count()] + 1
        valid = [i for i in range(1, length + 1) if depth[i] < k]

        fact = [1] * (length + 1)
        for i in range(1, length + 1):
            fact[i] = fact[i - 1] * i % mod
        inv = [1] * (length + 1)
        inv[length] = pow(fact[length], mod - 2, mod)
        for i in range(length, 0, -1):
            inv[i - 1] = inv[i] * i % mod

        answer = 0
        used = 0
        for pos, ch in enumerate(s):
            if ch == '1':
                # Match the preceding prefix, then place 0 here.
                rem = length - pos - 1
                subtotal = 0
                for w in valid:
                    t = w - used
                    if t < 0:
                        continue
                    if t > rem:
                        break
                    subtotal += inv[t] * inv[rem - t] % mod
                answer = (answer + fact[rem] * (subtotal % mod)) % mod
                used += 1
        return answer

