from typing import List

class Solution:
    def permute(self, n: int, k: int) -> List[int]:
        fact = [1] * (n + 1)
        for i in range(1, n + 1):
            fact[i] = fact[i - 1] * i
        remaining = list(range(1, n + 1))
        odds, evens = (n + 1) // 2, n // 2
        answer = []
        last = -1
        while remaining:
            r = len(remaining) - 1
            for i, value in enumerate(remaining):
                parity = value % 2
                if parity == last:
                    continue
                o = odds - parity
                e = evens - (1 - parity)
                needed_odds = (r + 1) // 2 if parity == 0 else r // 2
                if o != needed_odds:
                    continue
                count = fact[o] * fact[e]
                if k > count:
                    k -= count
                else:
                    answer.append(value)
                    remaining.pop(i)
                    odds, evens = o, e
                    last = parity
                    break
            else:
                return []
        return answer

