from math import gcd

class Solution:
    def largestPalindrome(self, n: int, k: int) -> str:
        powers = [1 % k] * n
        for i in range(1, n):
            powers[i] = powers[i - 1] * 10 % k

        m = (n + 1) // 2
        weights = [0] * m
        for i in range(m):
            j = n - 1 - i
            weights[i] = powers[i] if i == j else (powers[i] + powers[j]) % k

        # Suffix digits can realize exactly the multiples of this gcd
        # modulo k, since 0..9 contains a full residue system modulo k.
        suffix = [k] * (m + 1)
        for i in range(m - 1, -1, -1):
            suffix[i] = gcd(suffix[i + 1], weights[i])

        result = ['0'] * n
        remainder = 0
        for i, weight in enumerate(weights):
            for digit in range(9, 0 if i == 0 else -1, -1):
                new_remainder = (remainder + digit * weight) % k
                if new_remainder % suffix[i + 1] == 0:
                    result[i] = result[n - 1 - i] = str(digit)
                    remainder = new_remainder
                    break

        return ''.join(result)

