    def maximumSubarrayXor(self, nums: List[int], queries: List[List[int]]) -> List[int]:
        n = len(nums)
        groups = [[] for _ in range(n)]
        for i, (l, r) in enumerate(queries):
            groups[l].append((r, i))
        answer = [0] * len(queries)
        score = [0] * n
        best = [0] * n
        for l in range(n - 1, -1, -1):
            s = nums[l]
            b = s
            score[l] = s
            best[l] = b
            for r in range(l + 1, n):
                s ^= score[r]
                score[r] = s
                if best[r] > b:
                    b = best[r]
                if s > b:
                    b = s
                best[r] = b
            for r, i in groups[l]:
                answer[i] = best[r]
        return answer

