class Solution:
    def makeStringGood(self, s: str) -> int:
        counts = [0] * 26
        for ch in s:
            counts[ord(ch) - 97] += 1
        answer = len(s)
        for target in range(1, max(counts) + 1):
            deleted = counts[0]
            kept = abs(counts[0] - target)
            previous = counts[0]
            for current in counts[1:]:
                best = min(deleted, kept)
                new_deleted = best + current
                if current >= target:
                    new_kept = best + current - target
                else:
                    deficit = target - current
                    new_kept = deficit + min(
                        deleted - min(previous, deficit),
                        kept - min(max(previous - target, 0), deficit)
                    )
                deleted, kept = new_deleted, new_kept
                previous = current
            answer = min(answer, deleted, kept)
        return answer

