class Solution:
    def shortestMatchingSubstring(self, s: str, p: str) -> int:
        parts = [part for part in p.split('*') if part]
        if not parts:
            return 0
        n = len(s)

        def occurrences(t):
            m = len(t)
            pi = [0] * m
            j = 0
            for i in range(1, m):
                while j and t[i] != t[j]:
                    j = pi[j - 1]
                if t[i] == t[j]:
                    j += 1
                pi[i] = j
            out = []
            j = 0
            for i, c in enumerate(s):
                while j and c != t[j]:
                    j = pi[j - 1]
                if c == t[j]:
                    j += 1
                if j == m:
                    out.append(i - m + 1)
                    j = pi[j - 1]
            return out

        positions = [occurrences(t) for t in parts]
        if any(not a for a in positions):
            return -1
        pointers = [0] * len(parts)
        answer = n + 1
        for start in positions[0]:
            end = start + len(parts[0])
            for k in range(1, len(parts)):
                a = positions[k]
                j = pointers[k]
                while j < len(a) and a[j] < end:
                    j += 1
                pointers[k] = j
                if j == len(a):
                    return answer if answer <= n else -1
                end = a[j] + len(parts[k])
            answer = min(answer, end - start)
        return answer if answer <= n else -1

