import sys


def solve(A, B):
    a = [i for i, c in enumerate(A) if c == 49]
    b = [i for i, c in enumerate(B) if c == 49]
    na = len(a)
    nb = len(b)
    if na < nb:
        return -1

    answer = 10**18
    for parity in (0, 1):
        j = 0
        start = (b[0] - parity) & 1
        valid = True
        for h in range(nb - 1):
            end = a[j] + ((a[j] - start) & 1)
            gap = b[h + 1] - b[h]
            while True:
                while j < na and a[j] <= end:
                    j += 1
                if j == na:
                    valid = False
                    break
                if a[j] >= end + gap:
                    break
                end = a[j] + ((a[j] - start) & 1)
            if not valid:
                break
            start = end + gap

        if valid:
            end = a[-1] + ((a[-1] - start) & 1)
            k = max(0, b[0] - a[0], end - b[-1])
            k += (k - parity) & 1
            answer = min(answer, k)

    return -1 if answer == 10**18 else answer


