import sys
import heapq


def solve():
    it = iter(map(int, sys.stdin.buffer.read().split()))
    n = next(it)
    W = next(it)
    groups = [[] for _ in range(W + 1)]
    for _ in range(n):
        w = next(it)
        v = next(it)
        if v > 1:
            groups[w].append(1 - v)

    dp = [0] * (W + 1)
    for w in range(1, W + 1):
        h = groups[w]
        if not h:
            continue
        # Merge the decreasing marginal-value sequences for this weight.
        heapq.heapify(h)
        p = [0]
        for _ in range(W // w):
            if h[0] >= 0:
                break
            a = h[0]
            p.append(p[-1] - a)
            heapq.heapreplace(h, a + 2)
        K = len(p) - 1
        if not K:
            continue
        if K == 1:
            a = p[1]
            for j in range(W, w - 1, -1):
                z = dp[j - w] + a
                if z > dp[j]:
                    dp[j] = z
            continue

        nd = dp[:]
        if W // w < 16:
            for k in range(1, K + 1):
                shift = k * w
                a = p[k]
                for j in range(shift, W + 1):
                    z = dp[j - shift] + a
                    if z > nd[j]:
                        nd[j] = z
        else:
            # Concavity of p makes the maximizing predecessor monotone.
            def rec(l, u, lo, hi):
                mid = (l + u) // 2
                best = -1
                opt = lo
                for s in range(max(lo, mid - K), min(mid, hi) + 1):
                    z = old[s] + p[mid - s]
                    if z > best:
                        best = z
                        opt = s
                out[mid] = best
                if l < mid:
                    rec(l, mid - 1, lo, opt)
                if mid < u:
                    rec(mid + 1, u, opt, hi)

            for r in range(w):
                old = dp[r::w]
                out = old[:]
                rec(1, len(old) - 1, 0, len(old) - 1)
                nd[r::w] = out
        dp = nd

    print(dp[W])


if __name__ == '__main__':
    solve()

