from typing import List

class Solution:
    def findAnswer(self, parent: List[int], s: str) -> List[bool]:
        n = len(parent)
        children = [[] for _ in range(n)]
        for i in range(1, n):
            children[parent[i]].append(i)

        # Each subtree occupies a contiguous interval in postorder.
        start = [0] * n
        end = [0] * n
        order = []
        stack = [0]
        while stack:
            x = stack.pop()
            if x >= 0:
                start[x] = len(order)
                stack.append(~x)
                stack.extend(reversed(children[x]))
            else:
                x = ~x
                order.append(s[x])
                end[x] = len(order)

        # Manacher's algorithm handles both odd and even palindrome lengths.
        t = '^#' + '#'.join(order) + '#$'
        radius = [0] * len(t)
        center = right = 0
