import sys


def solve():
    data = list(map(int, sys.stdin.buffer.read().split()))
    n, m, s, t = data[:4]
    s -= 1
    t -= 1
    graph = [[] for _ in range(n)]
    for i in range(4, len(data), 2):
        u = data[i] - 1
        v = data[i + 1] - 1
        graph[u].append(v)
        graph[v].append(u)
    del data

    def bfs(root):
        dist = [-1] * n
        dist[root] = 0
        queue = [root]
        for v in queue:
            nd = dist[v] + 1
            for w in graph[v]:
                if dist[w] < 0:
                    dist[w] = nd
                    queue.append(w)
        return dist

    ds = bfs(s)
    dt = bfs(t)
    d = ds[t]

    path = [t]
    while path[-1] != s:
        v = path[-1]
        for w in graph[v]:
            if ds[w] == ds[v] - 1:
                path.append(w)
                break

    # An extra neighbor at an internal path vertex permits a swap
    # with only two moves beyond the distance lower bound.
    if any(len(graph[v]) >= 3 for v in path[1:-1]):
        # Two different shortest paths give the exact lower bound.
        if sum(ds[v] + dt[v] == d for v in range(n)) > d + 1:
            print(2 * d)
            return

        # A path of length d+1 must use an edge within a BFS layer.
        for v in range(n):
            for w in graph[v]:
                if ds[v] == ds[w] and ds[v] + min(dt[v], dt[w]) == d:
                    print(2 * d + 1)
                    return
        print(2 * d + 2)
        return

    # All internal vertices of the chosen path have degree two.
    # Look for an alternative route between its endpoints.
    blocked = bytearray(n)
    for v in path[1:-1]:
        blocked[v] = 1
    dist = [-1] * n
    dist[s] = 0
    queue = [s]
    for v in queue:
        nd = dist[v] + 1
        for w in graph[v]:
            if blocked[w] or (v == s and w == t) or (v == t and w == s):
                continue
            if dist[w] < 0:
                dist[w] = nd
                queue.append(w)

    inf = 10**18
    answer = d + dist[t] if dist[t] >= 0 else inf

    # Otherwise, use a branching vertex beyond either endpoint.
    for v in range(n):
        if len(graph[v]) >= 3:
            candidate = 2 * d + 4 * min(ds[v], dt[v]) + 4
            if candidate < answer:
                answer = candidate

    print(answer if answer < inf else -1)


if __name__ == '__main__':
    solve()

