from math import isqrt


def main():
    n = int(sys.stdin.buffer.readline())
    root = isqrt(n)
    limit = root // 2
    if limit < 2:
        print(0)
        return

    sieve = bytearray(b'\x01') * (limit + 1)
    sieve[0:2] = b'\x00\x00'
    for p in range(2, isqrt(limit) + 1):
        if sieve[p]:
            start = p * p
            sieve[start::p] = b'\x00' * ((limit - start) // p + 1)
    primes = [p for p in range(2, limit + 1) if sieve[p]]

    # Nine divisors means either p^8 or p^2 * q^2 with distinct primes.
    answer = 0
    j = len(primes) - 1
    for i, p in enumerate(primes):
        while j > i and p * primes[j] > root:
            j -= 1
        if j <= i:
            break
        answer += j - i

    for p in primes:
        if p ** 8 > n:
            break
