from typing import List

class Solution:
    def countPairs(self, nums: List[int]) -> int:
        seen = {}
        answer = 0
        # Sorting ensures the longer number is processed last, so swaps
        # producing leading zeros are handled as well.
        for x in sorted(nums):
            digits = list(str(x))
            variants = {x}
            for i in range(len(digits)):
                for j in range(i + 1, len(digits)):
                    digits[i], digits[j] = digits[j], digits[i]
                    variants.add(int(''.join(digits)))
                    digits[i], digits[j] = digits[j], digits[i]
            answer += sum(seen.get(y, 0) for y in variants)
            seen[x] = seen.get(x, 0) + 1
        return answer

