        powers = []
        p = 1
        while p < limit:
            powers.append(p)
            p *= 10

        dist = [float('inf')] * limit
        dist[n] = n
        heap = [(n, n)]
        while heap:
            cost, x = heappop(heap)
            if cost != dist[x]:
                continue
            if x == m:
                return cost
            for p in powers:
                digit = (x // p) % 10
                if digit < 9:
                    y = x + p
                    nc = cost + y
                    if not prime[y] and nc < dist[y]:
                        dist[y] = nc
                        heappush(heap, (nc, y))
                if digit > 0:
                    y = x - p
                    if y >= low and not prime[y]:
                        nc = cost + y
                        if nc < dist[y]:
                            dist[y] = nc
                            heappush(heap, (nc, y))
        return -1

