class Solution:
    def beautifulSplits(self, nums: List[int]) -> int:
        n = len(nums)
        # z[i] is the common-prefix length of nums and nums[i:].
        z = [0] * n
        left = right = 0
        for i in range(1, n):
            if i < right:
                z[i] = min(right - i, z[i - left])
            while i + z[i] < n and nums[z[i]] == nums[i + z[i]]:
                z[i] += 1
            if i + z[i] > right:
                left, right = i, i + z[i]

        # Before processing i, dp[j] stores LCP(i+1, j).
        dp = [0] * (n + 1)
        answer = 0
        for i in range(n - 2, 0, -1):
            limit = (n + i) // 2
            if z[i] >= i:
                # All second cut positions j >= 2*i qualify.
                answer += max(0, n - 2 * i)
                # Count the other condition only outside that range.
                limit = min(limit, 2 * i - 1)

            value = nums[i]
            for j in range(i + 1, limit + 1):
                if value == nums[j]:
                    length = dp[j + 1] + 1
                    dp[j] = length
                    if length >= j - i:
                        answer += 1
                else:
                    dp[j] = 0

            for j in range(max(i + 1, limit + 1), n):
                if value == nums[j]:
                    dp[j] = dp[j + 1] + 1
                else:
                    dp[j] = 0

        return answer

