import heapq

class Solution:
    def minMaxWeight(self, n: int, edges: List[List[int]], threshold: int) -> int:
        graph = [[] for _ in range(n)]
        for a, b, w in edges:
            graph[b].append((a, w))
        dist = [1000001] * n
        dist[0] = 0
        heap = [(0, 0)]
        count = 0
        answer = 0
        while heap:
            cost, u = heapq.heappop(heap)
            if cost != dist[u]:
                continue
            count += 1
            answer = cost
            if count == n:
                return answer
            for v, w in graph[u]:
                candidate = max(cost, w)
                if candidate < dist[v]:
                    dist[v] = candidate
                    heapq.heappush(heap, (candidate, v))
        return -1

