for w in ['a'*250,'b'*250,'aeiou'*50,('aeioub'*42)[:250]]:
    for k in [0,1,125,245]:
        for _ in range(100): s.countOfSubstrings(w,k)
print('All checks passed; 1600 maximum-length calls:',time.perf_counter()-start)

class Solution:
    def countOfSubstrings(self, word: str, k: int) -> int:
        def at_most(limit):
            if limit < 0:
                return 0
            last = dict.fromkeys('aeiou', -1)
            left = consonants = total = 0
            for right, char in enumerate(word):
                if char in last:
                    last[char] = right
                else:
                    consonants += 1
                while consonants > limit:
                    if word[left] not in last:
                        consonants -= 1
                    left += 1
                earliest = min(last.values())
                if earliest >= left:
                    total += earliest - left + 1
            return total

        return at_most(k) - at_most(k - 1)

