                if (x1, y2) not in present or (x2, y1) not in present:
                    continue
                left, right = sorted((x1, x2))
                bottom, top = sorted((y1, y2))
                if sum(left <= x <= right and bottom <= y <= top for x, y in points) == 4:
                    best = max(best, (right - left) * (top - bottom))
        return best

